#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
	BOLD=$(tput bold)
	DIM=$(tput dim)
	RESET=$(tput sgr0)
	BLUE=$(tput setaf 4)
	GREEN=$(tput setaf 2)
	YELLOW=$(tput setaf 3)
	RED=$(tput setaf 1)
else
	BOLD=""
	DIM=""
	RESET=""
	BLUE=""
	GREEN=""
	YELLOW=""
	RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
	[[ -t 1 ]] || return 0
	if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
	_clear
	printf '\n%s%s  %s%s\n' "${BOLD}" "${BLUE}" "$1" "${RESET}"
	printf '%s  %s stages%s\n\n' "${DIM}" "${TOTAL_STAGES}" "${RESET}"
	printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "${DIM}"
	printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
	printf '  later — it remembers values already saved.%s\n' "${RESET}"
	pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
	_clear
	_STAGE_INDEX=$((_STAGE_INDEX + 1))
	printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
		"${BOLD}" "${BLUE}" "${_STAGE_INDEX}" "${TOTAL_STAGES}" "$1" "${RESET}"
}

# say "..." — a plain instruction line.
say() { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "${BLUE}" "${RESET}" "$1"; }
note() { printf '  %s%s%s\n' "${DIM}" "$1" "${RESET}"; }
warn() { printf '  %s⚠ %s%s\n' "${YELLOW}" "$1" "${RESET}"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
	local url="$1"
	printf '  %s↗ opening%s %s\n' "${GREEN}" "${RESET}" "${url}"
	{
		if command -v wslview >/dev/null 2>&1; then
			wslview "${url}"
		elif command -v explorer.exe >/dev/null 2>&1; then
			explorer.exe "${url}"
		elif command -v xdg-open >/dev/null 2>&1; then
			xdg-open "${url}"
		elif command -v open >/dev/null 2>&1; then
			open "${url}"
		else warn "couldn't open a browser — visit it manually: ${url}"; fi
	} >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: ${url}"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
	printf '  %s%s%s ' "${DIM}" "${1:-Press Enter to continue}" "${RESET}"
	read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
	local reply=""
	printf '  %s? %s [y/N] ' "${YELLOW}" "$1"
	read -r reply || true
	[[ ${reply} =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
	[[ -f ${ENV_FILE} ]] || return 1
	local line
	line=$(grep -E "^${1}=" "${ENV_FILE}" | tail -n1) || return 1
	printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
	local key="$1" prompt="$2" current input
	current=$(_existing "${key}" || true)
	if [[ -n ${current} ]]; then
		printf '  %s%s%s %s[Enter keeps current]%s ' "${BOLD}" "${prompt}" "${RESET}" "${DIM}" "${RESET}"
	else
		printf '  %s%s%s ' "${BOLD}" "${prompt}" "${RESET}"
	fi
	read -r input || true
	[[ -z ${input} && -n ${current} ]] && input="${current}"
	printf -v "${key}" '%s' "${input}"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
	local key="$1" prompt="$2" current input
	current=$(_existing "${key}" || true)
	if [[ -n ${current} ]]; then
		printf '  %s%s%s %s[Enter keeps current]%s ' "${BOLD}" "${prompt}" "${RESET}" "${DIM}" "${RESET}"
	else
		printf '  %s%s%s ' "${BOLD}" "${prompt}" "${RESET}"
	fi
	read -rs input || true
	printf '\n'
	[[ -z ${input} && -n ${current} ]] && input="${current}"
	printf -v "${key}" '%s' "${input}"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
	local key="$1" value="$2" tmp
	touch "${ENV_FILE}"
	tmp=$(mktemp)
	grep -vE "^${key}=" "${ENV_FILE}" >"${tmp}" || true
	printf '%s=%s\n' "${key}" "${value}" >>"${tmp}"
	mv "${tmp}" "${ENV_FILE}"
	WRITTEN_ENV+=("${key}")
	printf '  %s✓ wrote%s %s → %s\n' "${GREEN}" "${RESET}" "${key}" "${ENV_FILE}"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
	local name="$1" value="$2"
	if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
		if printf '%s' "${value}" | gh secret set "${name}" >/dev/null 2>&1; then
			WRITTEN_SECRET+=("${name}")
			printf '  %s✓ set%s GitHub secret %s\n' "${GREEN}" "${RESET}" "${name}"
			return
		fi
	fi
	SKIPPED+=("GitHub secret ${name} (set it manually: gh secret set ${name})")
	warn "skipped GitHub secret ${name} — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
	local name="$1" value="$2"
	if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
		if gh variable set "${name}" --body "${value}" >/dev/null 2>&1; then
			printf '  %s✓ set%s GitHub variable %s\n' "${GREEN}" "${RESET}" "${name}"
			return
		fi
	fi
	SKIPPED+=("GitHub variable ${name}")
	warn "skipped GitHub variable ${name} — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
	_clear
	printf '\n%s%s  ✓ Setup complete%s\n' "${BOLD}" "${GREEN}" "${RESET}"
	((${#WRITTEN_ENV[@]})) && note "wrote ${#WRITTEN_ENV[@]} value(s) to ${ENV_FILE}: ${WRITTEN_ENV[*]}"
	((${#WRITTEN_SECRET[@]})) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
	if ((${#SKIPPED[@]})); then
		printf '\n'
		warn "still to do by hand:"
		for s in "${SKIPPED[@]}"; do note "  - ${s}"; done
	fi
	printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "${ROOT}"
ENV_FILE="${ROOT}/shallot-infra/.env"
TLS_DEFAULT="${HOME}/.local/share/shallot/wazuh-tls-input"
AGENT_DEFAULT="${HOME}/.local/share/shallot/wazuh-agent"
COMPOSE_FILES=(
	-f compose.yml
	-f compose.wazuh.yml
	-f compose.wazuh-tls.override.yml
	-f compose.wazuh-agent.override.yml
	--profile wazuh-secure
)

die() { warn "$1"; exit 1; }

compose() {
	(
		cd "${ROOT}/shallot-infra" &&
			SHALLOT_WAZUH_TLS_INPUT_DIR="${SHALLOT_WAZUH_TLS_INPUT_DIR}" \
				SHALLOT_WAZUH_AGENT_DIR="${SHALLOT_WAZUH_AGENT_DIR}" \
				podman-compose "${COMPOSE_FILES[@]}" "$@"
	)
}

env_has() { [[ -n "$(_existing "$1" || true)" ]]; }

cert_pub() {
	openssl x509 -in "$1" -pubkey -noout 2>/dev/null |
		openssl pkey -pubin -outform der 2>/dev/null |
		sha256sum | cut -d' ' -f1
}

key_pub() {
	openssl pkey -in "$1" -pubout -outform der 2>/dev/null |
		sha256sum | cut -d' ' -f1
}

banner "SHALLOT — Wazuh secure lab bring-up"

stage "Preflight"
say "Checking local tools, repository layout, and runtime policy."
for cmd in ansible-playbook podman podman-compose python3 openssl curl; do
	command -v "${cmd}" >/dev/null 2>&1 || die "missing required command: ${cmd}"
done
python3 -c 'import yaml' 2>/dev/null || die "python3 PyYAML is required"
if ! command -v bsdtar >/dev/null 2>&1 &&
	! { command -v rpm2cpio >/dev/null 2>&1 && command -v cpio >/dev/null 2>&1; }; then
	die "need bsdtar, or rpm2cpio and cpio, to unpack the agent package"
fi
[[ -f "${ROOT}/ansible/playbooks/bootstrap_wazuh.yml" ]] ||
	die "not a SHALLOT checkout: ${ROOT}"
( cd "${ROOT}/ansible" && python3 scripts/check_runtime_policy.py ) ||
	die "runtime policy check failed"
if podman ps --format '{{.Names}}' 2>/dev/null | grep -q '^shallot-wazuh'; then
	warn "Wazuh containers are already running; the start stage is idempotent."
fi
say "Preflight passed."
pause

stage "Wazuh credentials"
say "Six random passwords and bcrypt hashes are generated locally."
say "Output: shallot-infra/.env and internal_users.local.yml, both mode 0600."
say "Nothing is printed. Rotation is a separate reviewed operation."
CRED_USERS="${ROOT}/shallot-infra/config/wazuh_indexer/internal_users.local.yml"
if [[ -f "${ENV_FILE}" && -f "${CRED_USERS}" ]]; then
	say "Credentials already exist; skipping generation."
elif [[ -f "${ENV_FILE}" || -f "${CRED_USERS}" ]]; then
	die "partial credential state: only one of the two files exists. Resolve manually."
else
	say "This pulls the pinned Wazuh indexer image (network required)."
	confirm "Generate the local Wazuh credentials now?" ||
		die "stopped before credential generation"
	( cd "${ROOT}/ansible" && ansible-playbook playbooks/bootstrap_wazuh.yml \
		-e shallot_wazuh_bootstrap_enabled=true \
		-e shallot_wazuh_bootstrap_allow_pull=true ) ||
		die "credential bootstrap failed"
fi
for f in "${ENV_FILE}" "${CRED_USERS}"; do
	[[ -f "${f}" ]] || die "missing generated file: ${f}"
	[[ "$(stat -c %a "${f}")" == "600" ]] ||
		die "wrong mode on ${f} (expected 600)"
done
say "Credentials present with mode 0600."
pause

stage "TLS input"
say "The runtime expects the official wazuh-certs-tool layout."
ask SHALLOT_WAZUH_TLS_INPUT_DIR "TLS input directory:"
: "${SHALLOT_WAZUH_TLS_INPUT_DIR:=${TLS_DEFAULT}}"
SHALLOT_WAZUH_TLS_INPUT_DIR="${SHALLOT_WAZUH_TLS_INPUT_DIR/#\~/${HOME}}"
[[ -d "${SHALLOT_WAZUH_TLS_INPUT_DIR}" ]] ||
	die "TLS input directory not found: ${SHALLOT_WAZUH_TLS_INPUT_DIR}. Certificate generation is a separate reviewed increment (ADR 0014/0015)."

fail=0
for rel in root-ca.pem indexer.pem indexer-key.pem \
	admin/admin.pem admin/admin-key.pem \
	filebeat/filebeat.pem filebeat/filebeat-key.pem; do
	[[ -f "${SHALLOT_WAZUH_TLS_INPUT_DIR}/${rel}" ]] || {
		warn "missing ${rel}"
		fail=1
	}
done
for rel in indexer-key.pem admin/admin-key.pem filebeat/filebeat-key.pem; do
	mode=$(stat -c %a "${SHALLOT_WAZUH_TLS_INPUT_DIR}/${rel}" 2>/dev/null || true)
	[[ "${mode}" == "600" ]] || {
		warn "${rel} mode ${mode:-missing} (expected 600)"
		fail=1
	}
done
sans=$(openssl x509 -in "${SHALLOT_WAZUH_TLS_INPUT_DIR}/indexer.pem" \
	-noout -ext subjectAltName 2>/dev/null || true)
for want in "DNS:wazuh-indexer.local" "DNS:localhost" "IP Address:127.0.0.1"; do
	grep -qF "${want}" <<<"${sans}" || {
		warn "indexer SAN missing: ${want}"
		fail=1
	}
done
openssl verify -CAfile "${SHALLOT_WAZUH_TLS_INPUT_DIR}/root-ca.pem" \
	"${SHALLOT_WAZUH_TLS_INPUT_DIR}/indexer.pem" \
	"${SHALLOT_WAZUH_TLS_INPUT_DIR}/admin/admin.pem" \
	"${SHALLOT_WAZUH_TLS_INPUT_DIR}/filebeat/filebeat.pem" >/dev/null 2>&1 || {
	warn "certificate chain verification failed"
	fail=1
}
for pair in "indexer.pem:indexer-key.pem" \
	"admin/admin.pem:admin/admin-key.pem" \
	"filebeat/filebeat.pem:filebeat/filebeat-key.pem"; do
	c=${pair%%:*}
	k=${pair#*:}
	cp=$(cert_pub "${SHALLOT_WAZUH_TLS_INPUT_DIR}/${c}")
	kp=$(key_pub "${SHALLOT_WAZUH_TLS_INPUT_DIR}/${k}")
	[[ -n "${cp}" && "${cp}" == "${kp}" ]] || {
		warn "private key does not match ${c}"
		fail=1
	}
done
((fail == 0)) ||
	die "TLS verification failed; see ansible/docs/wazuh-tls-verification-checklist.md"
say "TLS layout verified: seven files, key modes 0600, SANs, chain, key match."
pause

stage "Agent tree"
say "Builds var/ossec from the pinned 4.9.0 agent package (downloaded each run)."
say "The tree holds the enrollment key, so it must live outside the repository."
ask SHALLOT_WAZUH_AGENT_DIR "Agent tree directory:"
: "${SHALLOT_WAZUH_AGENT_DIR:=${AGENT_DEFAULT}}"
SHALLOT_WAZUH_AGENT_DIR="${SHALLOT_WAZUH_AGENT_DIR/#\~/${HOME}}"
[[ "${SHALLOT_WAZUH_AGENT_DIR}" == "${ROOT}" || "${SHALLOT_WAZUH_AGENT_DIR}" == "${ROOT}"/* ]] &&
	die "agent tree must live outside the repository"
python3 "${ROOT}/ansible/scripts/prepare_wazuh_agent.py" \
	--manager wazuh --target "${SHALLOT_WAZUH_AGENT_DIR}" ||
	die "agent tree build failed"
for rel in var/ossec/bin/wazuh-agentd var/ossec/etc/ossec.conf \
	var/ossec/etc/agent-name var/ossec/etc/client.keys; do
	[[ -f "${SHALLOT_WAZUH_AGENT_DIR}/${rel}" ]] ||
		die "agent tree missing ${rel}"
done
[[ "$(stat -c %a "${SHALLOT_WAZUH_AGENT_DIR}/var/ossec/etc/client.keys")" == "600" ]] ||
	die "enrollment key is not mode 0600"
say "Agent name: $(cat "${SHALLOT_WAZUH_AGENT_DIR}/var/ossec/etc/agent-name")"
pause

stage "Persist paths"
write_env SHALLOT_WAZUH_TLS_INPUT_DIR "${SHALLOT_WAZUH_TLS_INPUT_DIR}"
write_env SHALLOT_WAZUH_AGENT_DIR "${SHALLOT_WAZUH_AGENT_DIR}"
chmod 600 "${ENV_FILE}"
say ".env stays mode 0600; it also holds the generated Wazuh passwords."
pause

stage "Start Wazuh"
for key in WAZUH_INDEXER_PASSWORD WAZUH_FILEBEAT_PASSWORD; do
	env_has "${key}" || die "missing ${key} in ${ENV_FILE}"
done
say "Starting wazuh-indexer, wazuh, and wazuh-agent under profile wazuh-secure."
say "Images are digest-pinned and run rootless."
confirm "Start the Wazuh lab stack now?" || die "stopped before start"
compose up -d wazuh-indexer wazuh wazuh-agent || die "podman-compose up failed"
compose ps
pause

stage "Verify"
say "Waiting up to 120s for the indexer."
code=""
for _ in {1..60}; do
	code=$(curl -sS -o /dev/null -w '%{http_code}' --max-time 3 \
		--cacert "${SHALLOT_WAZUH_TLS_INPUT_DIR}/root-ca.pem" \
		--cert "${SHALLOT_WAZUH_TLS_INPUT_DIR}/admin/admin.pem" \
		--key "${SHALLOT_WAZUH_TLS_INPUT_DIR}/admin/admin-key.pem" \
		https://127.0.0.1:9200/ 2>/dev/null || true)
	[[ "${code}" == "200" ]] && break
	sleep 2
done
ok=1
if [[ "${code}" == "200" ]]; then
	say "Indexer: HTTP 200"
else
	warn "Indexer: last HTTP ${code:-none}"
	ok=0
fi
agent_ok=0
manager_ok=0
for _ in {1..60}; do
	agent_logs="$(podman logs --tail 200 shallot-wazuh-agent 2>&1 || true)
$(podman exec shallot-wazuh-agent tail -n 200 /var/ossec/logs/ossec.log 2>/dev/null || true)"
	manager_logs="$(podman logs --tail 400 shallot-wazuh 2>&1 || true)
$(podman exec shallot-wazuh tail -n 200 /var/ossec/logs/ossec.log 2>/dev/null || true)"
	[[ "${agent_logs}" == *"Connected to the server"* ]] && agent_ok=1
	[[ "${manager_logs}" == *"New wazuh agent connected"* ]] && manager_ok=1
	((agent_ok && manager_ok)) && break
	sleep 2
done
if ((agent_ok)); then
	say "Agent: connected to the manager"
else
	warn "Agent: no connection logged yet"
	ok=0
fi
if ((manager_ok)); then
	say "Manager: agent connection logged"
else
	warn "Manager: no agent connection logged yet"
	ok=0
fi
if ((ok)); then
	say "Verification passed."
else
	warn "Verification incomplete. Inspect: podman logs shallot-wazuh-indexer"
	warn "and: podman logs shallot-wazuh / shallot-wazuh-agent"
fi
pause

stage "Teardown (optional)"
say "Removes the three containers; keeps named volumes and the agent tree."
if confirm "Stop and remove the Wazuh containers?"; then
	compose down || warn "podman-compose down failed"
	say "Volumes kept. Remove them only if you intend to reset the lab."
else
	say "Left running."
fi

finish
